import { execFileSync } from "node:child_process";
import { relative, sep } from "node:path";
import { ESLint } from "eslint";

const SOURCE_FILE = /\.(?:cjs|mjs|js|jsx|cts|mts|ts|tsx)$/u;

// next-env.d.ts is generated by Next.js, is tracked for bootstrap convenience,
// and is intentionally ignored by ESLint. Every other tracked JS/TS-family file
// must be visible to the canonical "eslint ." traversal.
const INTENTIONALLY_GENERATED_TRACKED_FILES = new Set(["next-env.d.ts"]);

const trackedFiles = execFileSync("git", ["ls-files", "-z"], {
  encoding: "utf8",
})
  .split("\0")
  .filter(Boolean);

const trackedSet = new Set(trackedFiles);
const trackedSourceFiles = trackedFiles.filter((file) => SOURCE_FILE.test(file));
const expectedActiveSourceFiles = trackedSourceFiles.filter(
  (file) => !INTENTIONALLY_GENERATED_TRACKED_FILES.has(file),
);

const eslint = new ESLint({ errorOnUnmatchedPattern: false });
const results = await eslint.lintFiles(["."]);

const toRepoPath = (filePath) =>
  relative(process.cwd(), filePath).split(sep).join("/");

const lintedFiles = results.map((result) => toRepoPath(result.filePath));
const lintedSet = new Set(lintedFiles);
const missingFromTraversal = expectedActiveSourceFiles.filter(
  (file) => !lintedSet.has(file),
);
const lintedButUntracked = lintedFiles.filter((file) => !trackedSet.has(file));

const bySubsystem = {};
for (const file of expectedActiveSourceFiles) {
  const slash = file.indexOf("/");
  const subsystem = slash === -1 ? "(root)" : file.slice(0, slash);
  bySubsystem[subsystem] = (bySubsystem[subsystem] ?? 0) + 1;
}

const errorCount = results.reduce((sum, result) => sum + result.errorCount, 0);
const warningCount = results.reduce((sum, result) => sum + result.warningCount, 0);

const report = {
  schema: "velmere.c14-p06-eslint-coverage.v1",
  trackedFiles: trackedFiles.length,
  trackedJsTsFamilyFiles: trackedSourceFiles.length,
  intentionallyGeneratedTrackedFiles: [
    ...INTENTIONALLY_GENERATED_TRACKED_FILES,
  ],
  expectedActiveSourceFiles: expectedActiveSourceFiles.length,
  eslintTraversalFiles: lintedFiles.length,
  eslintErrors: errorCount,
  eslintWarnings: warningCount,
  subsystemCounts: Object.fromEntries(
    Object.entries(bySubsystem).sort(([a], [b]) => a.localeCompare(b)),
  ),
  missingFromTraversal,
  lintedButUntracked,
};

console.log(JSON.stringify(report, null, 2));

if (missingFromTraversal.length > 0) {
  console.error(
    "ESLint coverage guard failed: tracked active source is missing from eslint . traversal.",
  );
  process.exitCode = 2;
}
